CREATE TABLE client_progress_statement_boq_items (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,statement_id BIGINT UNSIGNED NOT NULL,contract_boq_item_id BIGINT UNSIGNED NOT NULL,section_code_snapshot VARCHAR(30) NULL,section_title_snapshot VARCHAR(190) NULL,item_code_snapshot VARCHAR(50) NULL,description_snapshot VARCHAR(1000) NULL,unit_name_snapshot VARCHAR(100) NULL,unit_symbol_snapshot VARCHAR(30) NULL,contract_quantity_snapshot DECIMAL(18,4) NULL,unit_rate_snapshot DECIMAL(18,2) NULL,previous_quantity DECIMAL(18,4) NULL,current_quantity DECIMAL(18,4) NOT NULL DEFAULT 0.0000,cumulative_quantity DECIMAL(18,4) NULL,previous_amount DECIMAL(18,2) NULL,current_amount DECIMAL(18,2) NULL,cumulative_amount DECIMAL(18,2) NULL,is_committed TINYINT(1) NOT NULL DEFAULT 0,sort_order INT UNSIGNED NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_cps_boq_statement_item(statement_id,contract_boq_item_id),KEY idx_cps_boq_item_history(contract_boq_item_id,is_committed),KEY idx_cps_boq_statement_order(statement_id,sort_order,id),CONSTRAINT fk_cps_boq_statement FOREIGN KEY(statement_id) REFERENCES client_progress_statements(id) ON DELETE RESTRICT,CONSTRAINT fk_cps_boq_contract_item FOREIGN KEY(contract_boq_item_id) REFERENCES contract_boq_items(id) ON DELETE RESTRICT,CONSTRAINT chk_cps_boq_current_quantity CHECK(current_quantity>=0),CONSTRAINT chk_cps_boq_committed CHECK(is_committed IN(0,1)),CONSTRAINT chk_cps_boq_sort CHECK(sort_order>0),CONSTRAINT chk_cps_boq_snapshots CHECK((is_committed=0 AND section_code_snapshot IS NULL AND section_title_snapshot IS NULL AND item_code_snapshot IS NULL AND description_snapshot IS NULL AND unit_name_snapshot IS NULL AND unit_symbol_snapshot IS NULL AND contract_quantity_snapshot IS NULL AND unit_rate_snapshot IS NULL AND previous_quantity IS NULL AND cumulative_quantity IS NULL AND previous_amount IS NULL AND current_amount IS NULL AND cumulative_amount IS NULL) OR (is_committed=1 AND section_code_snapshot IS NOT NULL AND section_title_snapshot IS NOT NULL AND description_snapshot IS NOT NULL AND contract_quantity_snapshot IS NOT NULL AND unit_rate_snapshot IS NOT NULL AND previous_quantity IS NOT NULL AND cumulative_quantity IS NOT NULL AND previous_amount IS NOT NULL AND current_amount IS NOT NULL AND cumulative_amount IS NOT NULL AND cumulative_quantity=previous_quantity+current_quantity AND cumulative_quantity<=contract_quantity_snapshot AND cumulative_amount=previous_amount+current_amount))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
